import { test } from "node:test";
import assert from "node:assert/strict";
import { first } from "../array.js";
import { isEven } from "../number.js";
import { keys } from "../object.js";

test("basics", () => { assert.equal(first([1]), 1); assert.ok(isEven(2)); assert.deepEqual(keys({ a: 1 }), ["a"]); });
